From 2d41c8b97a31bde32c653abe0b018e6e27c88fc1 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:04:08 +0100
Subject: [PATCH] editor/vlan: offer bonds, bridges and teams as parent
 connections

The parent drop-down of a VLAN connection only listed wired connections,
so a VLAN on top of a bond, bridge or team could only be set up by typing
the interface name. List those connection types as parents as well.

BUG: 470149
---
 libs/editor/settings/vlanwidget.cpp | 13 ++++++++++++-
 1 file changed, 12 insertions(+), 1 deletion(-)

diff --git a/libs/editor/settings/vlanwidget.cpp b/libs/editor/settings/vlanwidget.cpp
index ab64aafc0..0b582ba00 100644
--- a/libs/editor/settings/vlanwidget.cpp
+++ b/libs/editor/settings/vlanwidget.cpp
@@ -81,8 +81,19 @@ void VlanWidget::fillConnections()
     m_ui->parent->clear();

     for (const NetworkManager::Connection::Ptr &con : NetworkManager::listConnections()) {
-        if (!con->settings()->isSlave() && con->settings()->connectionType() == NetworkManager::ConnectionSettings::Wired)
+        if (con->settings()->isSlave()) {
+            continue;
+        }
+        switch (con->settings()->connectionType()) {
+        case NetworkManager::ConnectionSettings::Wired:
+        case NetworkManager::ConnectionSettings::Bond:
+        case NetworkManager::ConnectionSettings::Bridge:
+        case NetworkManager::ConnectionSettings::Team:
             m_ui->parent->addItem(con->name(), con->uuid());
+            break;
+        default:
+            break;
+        }
     }
 }

